{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://poseidon.example/schemas/applicability-rule.schema.json",
  "title": "POSEIDON v46.2 Applicability Rule",
  "type": "object",
  "required": ["ruleId", "version", "source", "lifecycle", "scope", "when", "then", "unknownPolicy"],
  "properties": {
    "ruleId": {"type": "string"},
    "version": {"type": "integer", "minimum": 1},
    "titleTr": {"type": "string"},
    "titleEn": {"type": "string"},
    "source": {
      "type": "object",
      "required": ["sourceId", "locator", "authorityLayer"],
      "properties": {
        "sourceId": {"type": "string"},
        "locator": {"type": "string"},
        "authorityLayer": {"enum": ["INTERNATIONAL", "FLAG", "CLASS_RO", "COMPANY_SMS", "OEM", "INDUSTRY_ASSURANCE", "PRODUCT_CONTROL"]},
        "mandatory": {"type": "boolean"},
        "url": {"type": "string"}
      }
    },
    "lifecycle": {
      "type": "object",
      "required": ["state", "effectiveFrom"],
      "properties": {
        "state": {"enum": ["DRAFT", "ADOPTED", "AWAITING", "FUTURE_EFFECTIVE", "IN_FORCE", "SUPERSEDED"]},
        "effectiveFrom": {"type": "string", "format": "date"},
        "effectiveTo": {"type": ["string", "null"], "format": "date"},
        "supersedes": {"type": ["string", "null"]}
      }
    },
    "scope": {
      "type": "object",
      "properties": {
        "modes": {"type": "array", "items": {"enum": ["SHIP", "TUG"]}},
        "flags": {"type": "array", "items": {"type": "string"}},
        "classSocieties": {"type": "array", "items": {"type": "string"}},
        "vesselTypes": {"type": "array", "items": {"type": "string"}},
        "operationTypes": {"type": "array", "items": {"type": "string"}}

}
    },
    "when": {"$ref": "#/$defs/expression"},
    "then": {
      "type": "object",
      "required": ["result"],
      "properties": {
        "result": {"enum": ["APPLICABLE", "NOT_APPLICABLE", "REVIEW_REQUIRED"]},
        "activate": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["type", "id"],
            "properties": {
              "type": {"enum": ["REQUIREMENT", "CONTROL", "SCREEN", "FIELD", "EVIDENCE_POLICY", "VERIFICATION_GATE", "TEST_CASE", "NOTIFICATION"]},
              "id": {"type": "string"}
            }
          }
        },
        "stateEffect": {"type": ["string", "null"]},
        "reasonCode": {"type": "string"}
      }
    },
    "unknownPolicy": {"enum": ["REVIEW_REQUIRED", "NOT_APPLICABLE", "FAIL_CLOSED"]},
    "priority": {"type": "integer", "minimum": 0},
    "requiresHumanReview": {"type": "boolean"},
    "tags": {"type": "array", "items": {"type": "string"}}
  },
  "$defs": {
    "expression": {
      "oneOf": [
        {"type": "object", "required": ["all"], "properties": {"all": {"type": "array", "items": {"$ref": "#/$defs/expression"}}}},
        {"type": "object", "required": ["any"], "properties": {"any": {"type": "array", "items": {"$ref": "#/$defs/expression"}}}},
        {"type": "object", "required": ["not"], "properties": {"not": {"$ref": "#/$defs/expression"}}},
        {
          "type": "object",
          "required": ["field", "operator"],
          "properties": {
            "field": {"type": "string"},
            "operator": {"enum": ["EQ", "NE", "GT", "GTE", "LT", "LTE", "IN", "NOT_IN", "EXISTS", "IS_TRUE", "IS_FALSE", "DATE_GTE", "DATE_LT", "CONTAINS"]},

{"type": "SCREEN", "id": "imdg-control"},
      {"type": "CONTROL", "id": "CTRL-IMDG-DG"},
      {"type": "EVIDENCE_POLICY", "id": "EVID-IMDG-MANIFEST-DECLARATION"}
    ], "stateEffect": "DG_CONTROL_REQUIRED", "reasonCode": "IMDG_42_24_ACTIVE"},
    "unknownPolicy": "REVIEW_REQUIRED",
    "priority": 700,
    "requiresHumanReview": false,
    "tags": ["IMDG", "SHIP", "CARGO"]
  }
]

