        '200':
          description: Impact diff
  /rules/validate:
    post:
      summary: Validate a draft rule against schema, semantics and test bindings
      operationId: validateRule
      responses:
        '200': {description: Validation result}
  /rules/publish:
    post:
      summary: Publish an approved immutable rule version
      description: Requires regulatory approver role and separation-of-duties checks.
      operationId: publishRule
      responses:
        '200': {description: Published rule version}
components:
  schemas:
    EvaluationRequest:
      type: object
      required: [evaluationDate, context, vessel]
      properties:
        evaluationDate: {type: string, format: date}
        context: {$ref: '#/components/schemas/ContextSnapshot'}
        vessel: {type: object, additionalProperties: true}
        operation: {type: object, additionalProperties: true}
        cargo: {type: object, additionalProperties: true}
        equipment: {type: object, additionalProperties: true}
        crew: {type: object, additionalProperties: true}
        regulatory: {type: object, additionalProperties: true}
    ContextSnapshot:
      type: object
      required: [tenantId, mode]
      properties:
        tenantId: {type: string}
        mode: {type: string, enum: [SHIP, TUG]}
        vesselId: {type: string}
        operationId: {type: string}
        evaluationType: {type: string}
    EvaluationResponse:

type: object
      required: [evaluationId, result, ruleSetVersion, results]
      properties:
        evaluationId: {type: string}
        result: {$ref: '#/components/schemas/ApplicabilityResult'}
        ruleSetVersion: {type: string}
        results:
          type: array
          items: {$ref: '#/components/schemas/RuleResult'}
        humanReview:
          type: object
          properties:
            required: {type: boolean}
            ownerRole: {type: string}
            reason: {type: string}
    RuleResult:
      type: object
      required: [ruleId, ruleVersion, result]
      properties:
        ruleId: {type: string}
        ruleVersion: {type: integer}
        result: {$ref: '#/components/schemas/ApplicabilityResult'}
        reasonCode: {type: string}
        predicateTrace: {type: array, items: {type: object, additionalProperties: true}}
        activated: {type: array, items: {type: string}}
        missingInputs: {type: array, items: {type: string}}
        conflicts: {type: array, items: {type: string}}
    ApplicabilityResult:
      type: string
      enum: [APPLICABLE, NOT_APPLICABLE, REVIEW_REQUIRED]
    Explanation:
      type: object
      properties:
        evaluationId: {type: string}
        targetId: {type: string}
        result: {$ref: '#/components/schemas/ApplicabilityResult'}
        sourceIds: {type: array, items: {type: string}}
        reasonTree: {type: array, items: {type: object, additionalProperties: true}}
        nextActions: {type: array, items: {type: string}}
    VersionRef:

type: object
      properties:
        evaluationDate: {type: string, format: date}
        ruleSetVersion: {type: string}
